import{_ as t,o as a,c as n,aB as s}from"./chunks/framework.BrtqxvdK.js";const g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":null}'),o={name:"architecture.md"};function i(r,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h1><p>The scaffold produces a <strong>two-layer client</strong>:</p><ul><li><p><strong><code>src/api/</code></strong> — generated by <a href="https://openapi-generator.tech/" target="_blank" rel="noreferrer">OpenAPI Generator</a> (<code>julia-client</code>), committed to the repo as plain Julia source. Java is needed <em>only</em> when scaffolding or regenerating; end users of the package never need it.</p></li><li><p><strong><code>src/client/</code></strong> — hand-written ergonomic overlay. Wraps the generated <code>OpenAPI.Clients.Client</code>, adds auth strategies, composable reliability primitives, pagination iterators, and pretty <code>show</code> for generated model types.</p></li></ul><h2 id="Why-two-layers" tabindex="-1">Why two layers <a class="header-anchor" href="#Why-two-layers" aria-label="Permalink to &quot;Why two layers {#Why-two-layers}&quot;">​</a></h2><p>The <code>julia-client</code> generator is BETA and produces low-level bindings: each operation is a method on an API-set struct (e.g. <code>get_pet_by_id(::PetApi, ::Int64)</code> rather than a free function), and auth schemes beyond bearer/basic/api-key aren&#39;t supported. The hand-written layer exists to absorb those rough edges:</p><ul><li><p>Free-function ergonomics via <code>using .GeneratedAPI</code> re-exports</p></li><li><p>OAuth2 / SigV4 / signing schemes implemented as <code>Auth</code> subtypes that inject headers via <code>pre_request_hook</code></p></li><li><p>Reliability stack (<code>with_defaults</code>) composes around any generated endpoint call, no per-endpoint plumbing required</p></li><li><p>Typed errors map non-2xx responses to <code>APIError</code> subtypes so callers pattern-match instead of inspecting integers</p></li></ul><h2 id="Scaffold-pipeline" tabindex="-1">Scaffold pipeline <a class="header-anchor" href="#Scaffold-pipeline" aria-label="Permalink to &quot;Scaffold pipeline {#Scaffold-pipeline}&quot;">​</a></h2><p>The <code>APIWrapper</code> factory composes five <code>OpenAPITemplate</code> plugins on top of the standard PkgTemplates plugins (<code>ProjectFile</code>, <code>SrcDir</code>, <code>Readme</code>, <code>License</code>, <code>Git</code>, <code>Formatter</code>, <code>GitHubActions</code>, <code>Codecov</code>, <code>CompatHelper</code>, <code>TagBot</code>). Each runs in a <code>posthook</code> at a specific priority:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Priority</th><th style="text-align:right;">Plugin</th><th style="text-align:right;">What it writes</th></tr></thead><tbody><tr><td style="text-align:right;">200</td><td style="text-align:right;"><code>ClientLayer</code></td><td style="text-align:right;"><code>src/&lt;PKG&gt;.jl</code>, <code>src/client/{auth,errors,retry,rate_limit,timeout,logging,middleware,Client,pagination,show}.jl</code>, runtime deps in <code>Project.toml</code>, custom <code>README.md</code>, <code>.gitignore</code> extras</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;"><code>OpenAPISpec</code></td><td style="text-align:right;">(only if <code>spec_url</code> set) saves <code>spec/openapi.json</code>, normalises to OAS 3, runs codegen, writes <code>gen/{openapi-config.json,regenerate.jl}</code>, <code>scaffold-info.toml</code>, <code>.gitattributes</code>, drift-check workflow</td></tr><tr><td style="text-align:right;">50</td><td style="text-align:right;"><code>BrokenRecordTests</code></td><td style="text-align:right;">Full <code>test/</code> tree (auto-walking <code>runtests.jl</code> + per-component test files + opt-in cassette / mocking skeletons)</td></tr><tr><td style="text-align:right;">25</td><td style="text-align:right;"><code>VitepressDocs</code></td><td style="text-align:right;"><code>docs/{Project.toml,package.json,make.jl}</code>, <code>docs/src/{index,getting_started,julia_reference,cassette_testing}.md</code>, per-tag <code>docs/src/api/&lt;tag&gt;.md</code> (built at make-time from the spec), GitHub Pages workflow</td></tr><tr><td style="text-align:right;">5</td><td style="text-align:right;"><code>Git</code></td><td style="text-align:right;">initial commit, <code>.gitignore</code> (with extras contributed via <code>gitignore(::ClientLayer)</code>)</td></tr></tbody></table><p><code>ClientLayer</code> runs first so subsequent plugins find a consistent module file to extend; <code>Git</code> runs last so it sees the finished tree.</p><h2 id="Dependency-model-—-who-needs-what,-when" tabindex="-1">Dependency model — who needs what, when <a class="header-anchor" href="#Dependency-model-—-who-needs-what,-when" aria-label="Permalink to &quot;Dependency model — who needs what, when {#Dependency-model-—-who-needs-what,-when}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Audience</th><th style="text-align:right;">Needs</th></tr></thead><tbody><tr><td style="text-align:right;">Maintainer running <code>Template(...)</code></td><td style="text-align:right;">Julia 1.10+, Java 11+, Node 18+ (for <code>npx</code>)</td></tr><tr><td style="text-align:right;">Maintainer running <code>gen/regenerate.jl</code></td><td style="text-align:right;">Java 11+, Node 18+</td></tr><tr><td style="text-align:right;">End user of the generated package</td><td style="text-align:right;">Julia 1.10+ — that&#39;s it</td></tr><tr><td style="text-align:right;">CI of the generated package</td><td style="text-align:right;">Julia (matrix); Node only on the docs job</td></tr><tr><td style="text-align:right;">The <code>regen-check.yml</code> weekly drift workflow</td><td style="text-align:right;">Java + Node (gated by <code>if:</code> to skip on PR builds)</td></tr></tbody></table><p>The promise: end users do not need Java. The committed <code>src/api/</code> is plain Julia; the generator&#39;s job is finished by the time the package is published.</p><h2 id="Generated-module-layout" tabindex="-1">Generated module layout <a class="header-anchor" href="#Generated-module-layout" aria-label="Permalink to &quot;Generated module layout {#Generated-module-layout}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PetstoreClient/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── PetstoreClient.jl          # \`module PetstoreClient ... end\`</span></span>
<span class="line"><span>│   ├── api/                       # GENERATED — DO NOT EDIT</span></span>
<span class="line"><span>│   │   ├── PetstoreClientAPI.jl</span></span>
<span class="line"><span>│   │   ├── modelincludes.jl</span></span>
<span class="line"><span>│   │   ├── apis/                  # one struct per spec tag</span></span>
<span class="line"><span>│   │   └── models/                # one mutable struct per spec schema</span></span>
<span class="line"><span>│   └── client/</span></span>
<span class="line"><span>│       ├── auth.jl                # NoAuth/BearerToken/APIKey/BasicAuth</span></span>
<span class="line"><span>│       ├── errors.jl              # APIError hierarchy + check_response</span></span>
<span class="line"><span>│       ├── logging.jl             # with_logging, redact_headers</span></span>
<span class="line"><span>│       ├── retry.jl               # RetryPolicy, with_retry, backoff_delay</span></span>
<span class="line"><span>│       ├── rate_limit.jl          # TokenBucket, acquire!, with_rate_limit</span></span>
<span class="line"><span>│       ├── timeout.jl             # with_timeout</span></span>
<span class="line"><span>│       ├── middleware.jl          # default_middleware, with_defaults</span></span>
<span class="line"><span>│       ├── Client.jl              # the user-facing struct</span></span>
<span class="line"><span>│       ├── pagination.jl          # paginate_cursor/offset/pagenum</span></span>
<span class="line"><span>│       └── show.jl                # pretty MIME&quot;text/plain&quot; for APIModel</span></span>
<span class="line"><span>├── spec/</span></span>
<span class="line"><span>│   ├── openapi.json               # canonical OAS 3 form (committed)</span></span>
<span class="line"><span>│   └── openapi.v2-original.json   # original Swagger 2.0 (if applicable)</span></span>
<span class="line"><span>├── gen/</span></span>
<span class="line"><span>│   ├── openapi-config.json        # pinned generator version + options</span></span>
<span class="line"><span>│   └── regenerate.jl              # \`julia gen/regenerate.jl\` to refresh</span></span>
<span class="line"><span>└── scaffold-info.toml             # spec URL + generator version + timestamp</span></span></code></pre></div><p>The next section walks through each <a href="./plugins">plugin</a> in turn.</p>`,16)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
